 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    marker_row = h - 1
    for c in range(w):
        if grid[marker_row][c] != 5:
            continue
        seeds = [(r, grid[r][c]) for r in range(h) if grid[r][c] != 0]
        # Every blank interval takes the color of the seed immediately below it;
        # blanks above the highest seed take that highest seed's color.
        if not seeds:
            continue
        first_r, first_color = seeds[0]
        for r in range(first_r):
            out[r][c] = first_color
        for (upper_r, _), (lower_r, lower_color) in zip(seeds, seeds[1:]):
            for r in range(upper_r + 1, lower_r):
                out[r][c] = lower_color
        last_r, last_color = seeds[-1]
        for r in range(last_r + 1, h):
            out[r][c] = last_color
    return out

if __name__ == '__main__':
    pass
